#!/usr/bin/env node
// Generates the gateway outputs from app-vue3/migrated-routes.json (+ syncs shared assets).
// Legacy is NOT an output: it fetches /migrated-routes.json from the gateway at runtime.
// (app-vue3's own manifest is generated by its `prebuild` script.)
//   node shared/scripts/generate.mjs           write files
//   node shared/scripts/generate.mjs --check   exit 1 if any generated file is stale (CI)
import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { loadRoutes, toGatewayManifest } from '../../app-vue3/scripts/routes-lib.mjs'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '../..')
const read = (p) => readFileSync(resolve(root, p), 'utf8')
const routes = loadRoutes(resolve(root, 'app-vue3/migrated-routes.json'))  // source of truth lives in app-vue3

// ---- renderers ------------------------------------------------------------
function nginx() {
  const out = [
    '# AUTO-GENERATED by shared/scripts/generate.mjs from app-vue3/migrated-routes.json',
    '# Do not edit by hand. Every route below is served by Vue 3 (unless cookie ui=legacy).',
    '',
  ]
  for (const r of routes) {
    const proxy = (loc) => [
      `location ${loc} {`,
      '  include /etc/nginx/proxy-common.conf;',
      '  proxy_pass http://$v3_upstream;',
      '  add_header X-Served-By $v3_upstream always;',
      '}',
    ]
    out.push(`# ${r.match}: ${r.path}${r.note ? ` — ${r.note}` : ''}`)
    out.push(...proxy(`= ${r.path}`), ...proxy(`= ${r.path}/`))
    if (r.match === 'prefix') out.push(...proxy(`^~ ${r.path}/`))
    out.push('')
  }
  return out.join('\n')
}

// ---- outputs: [target, content] ------------------------------------------
const outputs = {
  'gateway/migrated-paths.conf': nginx(),
  'gateway/migrated-routes.json': toGatewayManifest(routes),   // served at /migrated-routes.json
  // design tokens synced verbatim (plan pricing now lives in the backend, the single source of truth)
  'app-vue3/src/styles/pos.css': read('shared/pos.css'),
  'legacy-nuxt2/assets/pos.css': read('shared/pos.css'),
}

const check = process.argv.includes('--check')
let stale = 0
for (const [file, content] of Object.entries(outputs)) {
  const abs = resolve(root, file)
  const current = existsSync(abs) ? readFileSync(abs, 'utf8') : null
  if (check) {
    if (current !== content) { console.error(`STALE  ${file}`); stale++ }
    continue
  }
  mkdirSync(dirname(abs), { recursive: true })
  writeFileSync(abs, content)
  console.log(`wrote  ${file}`)
}
if (check) {
  if (stale) { console.error(`\n${stale} generated file(s) stale. Run: node shared/scripts/generate.mjs`); process.exit(1) }
  console.log('All generated files are up to date.')
}
